    // ── Issue #182: stake-event webhook URL config ───────────────────────────

    /// Maximum length in characters for the stored webhook URL.
    const MAX_WEBHOOK_URL_LENGTH: u32 = 200;

    /// Admin: store an off-chain webhook URL for indexers/monitoring bots to
    /// read. Purely metadata — the contract never calls this URL itself.
    /// Reverts with `DescriptionTooLong` if `url` exceeds 200 characters (the
    /// error enum is at the XDR-enforced 50-case cap, so this reuses the
    /// existing "value too long" variant rather than adding a new one).
    pub fn set_webhook_url(env: Env, admin: Address, url: String) -> Result<(), VaultError> {
        admin::require_admin_as(&env, &admin)?;
        if url.len() > Self::MAX_WEBHOOK_URL_LENGTH {
            return Err(VaultError::DescriptionTooLong);
        }
        balance::set_webhook_url(&env, &url);
        let admin = admin::get_admin(&env)?;
        events::webhook_url_updated(&env, &admin, &Some(url), env.ledger().sequence());
        Ok(())
    }

    /// Read-only query for the stored webhook URL. Returns `None` if unset.
    pub fn get_webhook_url(env: Env) -> Option<String> {
        balance::get_webhook_url(&env)
    }

    /// Admin: clears the stored webhook URL.
    pub fn clear_webhook_url(env: Env, admin: Address) -> Result<(), VaultError> {
        admin::require_admin_as(&env, &admin)?;
        balance::clear_webhook_url(&env);
        let admin = admin::get_admin(&env)?;
        events::webhook_url_updated(&env, &admin, &None, env.ledger().sequence());
        Ok(())
    }

    fn validate_rate_bps(rate_bps: u32) -> Result<(), VaultError> {
        if rate_bps > balance::MAX_RATE_BPS {
            return Err(VaultError::RateTooHigh);
        }
        Ok(())
    }

    fn build_position(env: &Env, user: &Address) -> Result<Option<StakePosition>, VaultError> {
        let shares = balance::get_shares(env, user);
        if shares == 0 {
            return Ok(None);
        }
        let total_shares = balance::get_total_shares(env);
        let total_deposited = balance::get_total_deposited(env);
        let amount = balance::shares_to_amount_with_decimals(
            total_shares,
            total_deposited,
            shares,
            balance::get_stake_decimals(env),
        )
            .ok_or(VaultError::ArithmeticError)?;
        let staked_at_ledger = env
            .storage()
            .persistent()
            .get::<_, u32>(&DataKey::StakedAtLedger(user.clone()))
            .unwrap_or(0);
        let last_claim_ledger = balance::get_last_claim_ledger(env, user);
        Ok(Some(StakePosition {
            amount,
            staked_at_ledger,
            last_claim_ledger,
        }))
    }

    fn pending_reward(env: &Env, user: &Address) -> Result<i128, VaultError> {
        let shares = balance::get_shares(env, user);
        if shares == 0 {
            return Ok(0);
        }
        let accrued = balance::get_accrued_reward(env, user);
        Ok(accrued)
    }

    fn pay_referral_bonus(
        env: &Env,
        referrer: &Address,
        referee: &Address,
        deposit_amount: i128,
    ) -> Result<(), VaultError> {
        if referrer == referee {
            return Err(VaultError::InvalidAddress);
        }
        let registry = balance::get_referral_registry(env);
        if !registry.iter().any(|registered| &registered == referrer) {
            return Err(VaultError::PositionNotFound);
        }

        let referrer_bps: u32 = env
            .storage()
            .instance()
            .get(&symbol_short!("ref_rb"))
            .unwrap_or(0);
        let referee_bps: u32 = env
            .storage()
            .instance()
            .get(&symbol_short!("ref_fb"))
            .unwrap_or(0);
        let bonus = |bps: u32| {
            deposit_amount
                .checked_mul(bps as i128)
                .and_then(|value| value.checked_div(10_000))
                .ok_or(VaultError::ArithmeticError)
        };
        let referrer_bonus = bonus(referrer_bps)?;
        let referee_bonus = bonus(referee_bps)?;
        let total_bonus = referrer_bonus
            .checked_add(referee_bonus)
            .ok_or(VaultError::ArithmeticError)?;
        let reward_pool = balance::get_reward_pool_balance(env);
        if total_bonus > reward_pool {
            return Err(VaultError::InsufficientRewardPool);
        }

        if total_bonus > 0 {
            let reward_token = Self::reward_token_address(env)?;
            let client = token::Client::new(env, &reward_token);
            let pool_address = env.current_contract_address();
            if client.balance(&pool_address) < total_bonus {
                return Err(VaultError::InsufficientRewardPool);
            }
            if referee_bonus > 0 {
                client.transfer(&pool_address, referee, &referee_bonus);
            }
            balance::set_reward_pool_balance(env, reward_pool - total_bonus);
        }

        balance::set_referrer_of(env, referee, referrer);
        balance::add_referee(env, referrer, referee);
        let mut stats = balance::get_referral_stats(env, referrer);
        stats.total_referred_deposits = stats
            .total_referred_deposits
            .checked_add(deposit_amount)
            .ok_or(VaultError::ArithmeticError)?;
        stats.referee_count = stats.referee_count.saturating_add(1);
        stats.earned = stats
            .earned
            .checked_add(referrer_bonus)
            .ok_or(VaultError::ArithmeticError)?;
        balance::set_referral_stats(env, referrer, &stats);
        events::referral_bonus_paid(
            env,
            referrer,
            referee,
            referrer_bonus,
            referee_bonus,
            env.ledger().sequence(),
        );
        Ok(())
    }

    fn normalize_to_reward_decimals(env: &Env, amount: i128) -> Result<i128, VaultError> {
        let stake_dec = balance::get_stake_decimals(env);
        let reward_dec = balance::get_reward_decimals(env);
        if stake_dec == reward_dec {
            return Ok(amount);
        }
        if reward_dec > stake_dec {
            let factor = 10i128.pow(reward_dec - stake_dec);
            amount
                .checked_mul(factor)
                .ok_or(VaultError::ArithmeticError)
        } else {
            let factor = 10i128.pow(stake_dec - reward_dec);
            Ok(amount / factor)
        }
    }

    fn require_not_paused(env: &Env) -> Result<(), VaultError> {
        balance::apply_scheduled_unpause_if_due(env);
        if env
            .storage()
            .instance()
            .get(&DataKey::Paused)
            .unwrap_or(false)
        {
            return Err(VaultError::VaultPaused);
        }
        Ok(())
    }

    /// Issue #525: reject new deposits once a graceful sunset has been started.
    /// Withdrawals, `unstake_all` and claims deliberately stay open, and the
    /// unstake fee is waived (see `do_unstake`/`withdraw_to`), so this is only
    /// called from the deposit paths.
    ///
    /// Issue #705: withdraw-only mode blocks deposits through the same gate,
    /// with the same `PoolShuttingDown` error (`VaultError` has no free slot).
    fn require_no_sunset(env: &Env) -> Result<(), VaultError> {
        if balance::get_sunset_exit_deadline(env).is_some() || withdraw_only_mode::is_active(env) {
            return Err(VaultError::PoolShuttingDown);
        }
        Ok(())
    }

    fn require_not_stopped(env: &Env) -> Result<(), VaultError> {
        if env.storage().instance().has(&DataKey::Stopped)
            && env
                .storage()
                .instance()
                .get(&DataKey::Stopped)
                .unwrap_or(false)
        {
            return Err(VaultError::ContractStopped);
        }
        if env.storage().instance().has(&symbol_short!("stopped"))
            && env
                .storage()
                .instance()
                .get(&symbol_short!("stopped"))
                .unwrap_or(false)
        {
            return Err(VaultError::ContractStopped);
        }
        Ok(())
    }

    fn append_changelog(env: &Env, _admin: &Address, _change_type: String, _old: i128, _new: i128) {
        let _ = env;
    }

    fn check_activation(_env: &Env) {}

    fn maybe_activate_rewards(_env: &Env) {}

    fn check_claim_rate_limit(_env: &Env, _user: &Address) {}

    fn do_stake_inner(env: &Env, user: &Address, amount: i128, min_shares_out: i128) -> Result<i128, VaultError> {
        // Issue #525: the `stake_and_claim` path must not slip past the sunset
        // gate that `stake` applies.

        let (p_dep, _) = crate::vault_extensions_490_493::VaultContract::get_pause_state(env.clone());
        if p_dep { return Err(VaultError::VaultPaused); }
        Self::require_no_sunset(env)?;

        if amount <= 0 {
            return Err(VaultError::ZeroAmount);
        }
        // Issue #542: same seed gate as `stake` for the `stake_and_claim` path.
        crate::vault_extensions_542_545::require_pool_seeded(env)?;
        // Issue #568: same unique-depositor cap as `stake`, so the
        // `stake_and_claim` path can't bypass it.
        Self::register_depositor(env, user)?;
        let token_addr: Address = env
            .storage()
            .instance()
            .get(&DataKey::Token)
            .ok_or(VaultError::NotInitialized)?;
        // Issue #512: credit what actually arrived, not the stated amount.
        let amount = crate::transfer_safety::pull_tokens(env, &token_addr, user, amount)?;
        let total_shares = balance::get_total_shares(env);
        let total_deposited = balance::get_total_deposited(env);
        let shares = balance::amount_to_shares_with_decimals(
            total_shares,
            total_deposited,
            amount,
            balance::get_stake_decimals(env),
        )
            .ok_or(VaultError::ArithmeticError)?;
        if min_shares_out > 0 && shares < min_shares_out {
            return Err(VaultError::InvalidRate);
        }

        let cur = balance::get_shares(env, user);
        balance::set_shares(env, user, cur + shares);
        balance::set_total_shares(env, total_shares + shares);
        balance::set_total_deposited(env, total_deposited.checked_add(amount).ok_or(VaultError::ArithmeticError)?);
        if cur == 0 {
            balance::register_staker(env, user);
        }
        // Issue #548: same large-deposit lock as `stake`.
        crate::vault_extensions_546_549::maybe_lock_deposit(env, user, amount, shares);
        crate::position_mirroring::maybe_mirror_action(env, user, symbol_short!("stake"), amount);
        crate::activity_log::record(
            env,
            user,
            crate::activity_log::ActivityKind::Deposit,
            amount,
            shares,
        );
        // Issue #544: single-shot low-balance alert on state-changing calls.
        crate::vault_extensions_542_545::check_and_emit_low_balance(env);
        Ok(shares)
    }

    pub(crate) fn do_unstake(env: &Env, staker: &Address, shares: i128) -> Result<i128, VaultError> {
        if shares <= 0 {
            return Err(VaultError::ZeroAmount);
        }
        let (_, withdrawals_paused) = crate::vault_extensions_490_493::VaultContract::get_pause_state(env.clone());
        if withdrawals_paused {
            return Err(VaultError::VaultPaused);
        }
        if Self::get_lock_status(env.clone(), staker.clone()).is_some() {
            return Err(VaultError::UseCooldownFlow);
        }
        if crate::vault_extensions_502_505::is_withdrawal_queue_enabled(env) {
            // Deduct shares so they can't queue the same shares twice, but don't pay out.
            let user_shares = balance::get_shares(env, staker);
            if user_shares < shares {
                return Err(VaultError::InsufficientShares);
            }
            crate::vault_extensions_502_505::enqueue_withdrawal(env, staker.clone(), shares);
            balance::set_shares(env, staker, user_shares - shares);
            return Ok(0); // Payout is deferred
        }
        let total_shares = balance::get_total_shares(env);
        let total_deposited = balance::get_total_deposited(env);
        let amount = balance::shares_to_amount_with_decimals(
            total_shares,
            total_deposited,
            shares,
            balance::get_stake_decimals(env),
        )
            .ok_or(VaultError::ArithmeticError)?;
        let token_addr = Self::token_address(env)?;
        let token_client = token::Client::new(env, &token_addr);
        token_client.transfer(&env.current_contract_address(), staker, &amount);
        balance::set_shares(env, staker, user_shares - shares);
        balance::set_total_shares(env, total_shares - shares);
        balance::set_total_deposited(env, total_deposited - amount);
        // Issue #453: trigger mirroring for unstake
        crate::position_mirroring::maybe_mirror_action(
            env,
            staker,
            symbol_short!("unstake"),
            amount,
        );
        Ok(amount)
    }

    /// Time-weighted average reward rate (basis points) across
    /// `[start_ledger, end_ledger)`, correctly accounting for a bootstrap
    /// window that only partially overlaps it (issue #202's requirement that
    /// "claims spanning the bootstrap boundary use time-weighted rates").
    ///
    /// Reward accrual (`reward_for_ledgers`) is linear in the rate, so
    /// substituting this single averaged rate for the whole window is
    /// mathematically equivalent to separately accruing the bootstrap
    /// portion at its own (also linear, hence average-at-midpoint) rate and
    /// the remaining portion at `base_rate`, then summing — without having
    /// to add bootstrap as a third kind of segment boundary alongside the
    /// existing boost-tier/campaign segment walk in `reward_between_ledgers`.
    // ── Issue #231: Halving Schedule ──────────────────────────────────────────

    /// Admin: set the halving schedule for reward rate reduction.
    /// `interval_ledgers` specifies how often the rate is reduced.
    /// `reduction_bps` is the share of the current rate removed at each
    /// interval (issue #701), between `1` and `10_000`; `5_000` is a classic
    /// halving. `floor_rate_bps` is the minimum rate enforced after reductions.
    pub fn set_halving_schedule(
        env: Env,
        admin: Address,
        interval_ledgers: u32,
        reduction_bps: u32,
        floor_rate_bps: i128,
    ) -> Result<(), VaultError> {
        admin::require_admin_as(&env, &admin)?;
        if interval_ledgers == 0 {
            return Err(VaultError::ZeroAmount);
        }
        if reduction_bps == 0 || reduction_bps > BOOST_BPS_BASE {
            return Err(VaultError::InvalidRate);
        }
        if floor_rate_bps < 0 {
            return Err(VaultError::ZeroAmount);
        }
        let config = HalvingConfig {
            interval_ledgers,
            started_at: env.ledger().sequence(),
            halving_count: 0,
            floor_rate_bps,
        };
        balance::set_halving_config(&env, &config);
        balance::set_halving_reduction_bps(&env, reduction_bps);
        Ok(())
    }

    /// Read-only: returns the current halving configuration, if set.
    pub fn get_halving_config(env: Env) -> Option<HalvingConfig> {
        balance::get_halving_config(&env)
    }

    /// Read-only: compute the current number of halvings that have occurred.
    pub fn get_current_halving_count(env: Env) -> u32 {
        balance::halving_count_at(&env, env.ledger().sequence())
    }

    /// Read-only: returns the ledger number of the next scheduled halving.
    pub fn next_halving_at(env: Env) -> Option<u32> {
        balance::next_halving_at(&env)
    }

    // ── Issue #222: Staking Certificate ────────────────────────────────────────

    /// Admin: set the minimum staked amount required for certificate eligibility.
    pub fn set_min_cert_amount(env: Env, admin: Address, amount: i128) -> Result<(), VaultError> {
        admin::require_admin_as(&env, &admin)?;
        if amount < 0 {
            return Err(VaultError::ZeroAmount);
        }
        balance::set_min_cert_amount(&env, amount);
        Ok(())
    }

    /// Read-only: returns the minimum staked amount for certificate eligibility.
    pub fn get_min_cert_amount(env: Env) -> i128 {
        balance::get_min_cert_amount(&env)
    }

    /// Admin: issue a staking certificate to a user.
    pub fn issue_certificate(
        env: Env,
        admin: Address,
        user: Address,
    ) -> Result<StakingCertificate, VaultError> {
        admin::require_admin_as(&env, &admin)?;

        let shares = balance::get_shares(&env, &user);
        let min_amount = balance::get_min_cert_amount(&env);
        if shares < min_amount {
            return Err(VaultError::ZeroAmount);
        }

        let counter = balance::get_certificate_counter(&env);
        let new_counter = counter.checked_add(1).ok_or(VaultError::ArithmeticError)?;
        balance::set_certificate_counter(&env, new_counter);

        // Certificate parameters
        let staked_since = env
            .storage()
            .persistent()
            .get::<_, u32>(&DataKey::StakedAtLedger(user.clone()))
            .unwrap_or(env.ledger().sequence());

        let current_ledger = env.ledger().sequence();
        let valid_for = LEDGERS_PER_DAY * 30; // 30 days validity
        let valid_until = current_ledger.saturating_add(valid_for);

        let cert = StakingCertificate {
            holder: user.clone(),
            min_amount_staked: min_amount,
            staked_since,
            issued_at: current_ledger,
            valid_until,
            certificate_id: new_counter,
        };

        balance::set_certificate(&env, &user, &cert);

        events::certificate_issued(&env, &user, new_counter, valid_until, current_ledger);

        Ok(cert)
    }

    /// Read-only: returns the staking certificate for a user, if any.
    pub fn get_certificate(env: Env, user: Address) -> Option<StakingCertificate> {
        balance::get_certificate(&env, &user)
    }

    /// Admin: invalidate a user's staking certificate.
    pub fn invalidate_certificate(
        env: Env,
        admin: Address,
        user: Address,
    ) -> Result<(), VaultError> {
        admin::require_admin_as(&env, &admin)?;

        let _cert = balance::get_certificate(&env, &user).ok_or(VaultError::ZeroAmount)?;

        // Remove the certificate from storage
        balance::remove_certificate(&env, &user);

        Ok(())
    }

    // ── Issue #233: Minimum Pool Size to Activate ─────────────────────────────

    /// Admin: set the minimum total staked amount required for the pool to be active.
    pub fn set_activation_threshold(
        env: Env,
        admin: Address,
        amount: i128,
    ) -> Result<(), VaultError> {
        admin::require_admin_as(&env, &admin)?;
        if amount < 0 {
            return Err(VaultError::ZeroAmount);
        }
        balance::set_activation_threshold(&env, amount);
        Ok(())
    }

    /// Read-only: returns the minimum total staked amount for activation.
    pub fn get_activation_threshold(env: Env) -> i128 {
        balance::get_activation_threshold(&env)
    }

    /// Read-only: returns whether the pool is active (total staked >= threshold).
    pub fn pool_is_active(env: Env) -> bool {
        let threshold = balance::get_activation_threshold(&env);
        let total_staked = balance::get_total_deposited(&env);
        if threshold <= 0 {
            return true;
        }
        total_staked >= threshold
    }

    /// Check activation status after a total_deposited change and emit events.
    fn check_activation(env: &Env) {
        let threshold = balance::get_activation_threshold(env);
        if threshold <= 0 {
            return;
        }
        let total_staked = balance::get_total_deposited(env);
        let was_active = balance::get_pool_was_active(env);
        let is_active = total_staked >= threshold;

        if is_active && !was_active {
            balance::set_pool_was_active(env, true);
            events::pool_activated(env, total_staked, threshold, env.ledger().sequence());
        } else if !is_active && was_active {
            balance::set_pool_was_active(env, false);
            events::pool_deactivated(env, total_staked, threshold, env.ledger().sequence());
        }
    }

    // ── Issue #232: Position Expiry ───────────────────────────────────────────

    /// Admin: set the maximum stake duration in ledgers before a position expires.
    pub fn set_max_stake_duration(
        env: Env,
        admin: Address,
        ledgers: u32,
    ) -> Result<(), VaultError> {
        admin::require_admin_as(&env, &admin)?;
        balance::set_max_stake_duration(&env, ledgers);
        Ok(())
    }

    /// Read-only: returns the maximum stake duration in ledgers (0 = no expiry).
    pub fn get_max_stake_duration(env: Env) -> u32 {
        balance::get_max_stake_duration(&env)
    }

    /// Read-only: returns whether the user's position has expired.
    pub fn position_expired(env: Env, user: Address) -> bool {
        let max_duration = balance::get_max_stake_duration(&env);
        if max_duration == 0 {
            return false;
        }
        let staked_at = match env
            .storage()
            .persistent()
            .get::<_, u32>(&DataKey::StakedAtLedger(user.clone()))
        {
            Some(ledger) => ledger,
            None => return false,
        };
        let current_ledger = env.ledger().sequence();
        let elapsed = current_ledger.saturating_sub(staked_at);
        elapsed >= max_duration
    }

    /// Emit position_expired event if the user's position just expired.
    fn maybe_emit_position_expired(env: &Env, user: &Address) {
        let max_duration = balance::get_max_stake_duration(env);
        if max_duration == 0 {
            return;
        }
        let staked_at = match env
            .storage()
            .persistent()
            .get::<_, u32>(&DataKey::StakedAtLedger(user.clone()))
        {
            Some(ledger) => ledger,
            None => return,
        };
        let current_ledger = env.ledger().sequence();
        let elapsed = current_ledger.saturating_sub(staked_at);
        if elapsed >= max_duration && !balance::get_position_expired_emitted(env, user) {
            balance::set_position_expired_emitted(env, user);
            events::position_expired(env, user, staked_at + max_duration, current_ledger);
        }
    }

    // ── Issue #234: Minimum Pool Size to Activate Rewards ─────────────────────

    /// Admin: set the minimum pool TVL required before reward accrual begins.
    ///
    /// While `total_deposited` has never reached `amount`, stakers accrue
    /// nothing — this stops an early-stage pool from draining its reward
    /// reserve to a handful of stakers. Pass `0` (the default) to disable the
    /// gate entirely, which is how every pool behaves that never calls this.
    ///
    /// Activation is a one-way latch: the first time TVL reaches the threshold
    /// the crossing ledger is recorded and accrual runs from there onward, so a
    /// later dip below the threshold does not retroactively void rewards
    /// already earned or silently stop future ones. Raising the threshold again
    /// after activation therefore does not re-arm the gate. Use `pause()` to
    /// halt an already-active pool.
    ///
    /// Setting a threshold the pool already satisfies activates rewards
    /// immediately, as of this call's ledger.
    ///
    /// Intended to be configured at pool setup, which is the case this issue
    /// targets. Arming the gate on a pool that is already below the threshold
    /// *and* has been accruing discards each staker's reward earned since their
    /// last checkpoint (their last stake, unstake, or claim); already-checkpointed
    /// `AccruedReward` is untouched. Have stakers claim first if arming late.
    pub fn set_min_pool_size_to_activate(
        env: Env,
        admin: Address,
        amount: i128,
    ) -> Result<(), VaultExtError> {
        admin::require_admin_as(&env, &admin)?;
        if amount < 0 {
            return Err(VaultExtError::ZeroAmount);
        }

        let old_amount = balance::get_min_pool_size(&env);
        balance::set_min_pool_size(&env, amount);

        let admin_actual = admin::get_admin(&env)?;
        events::min_pool_size_set(&env, &admin_actual, old_amount, amount);

        // A threshold the pool already meets takes effect right away rather
        // than waiting for the next stake to nudge TVL.
        Self::maybe_activate_rewards(&env);

        Ok(())
    }

    /// Read-only: the minimum pool TVL required for rewards to accrue.
    ///
    /// `0` means no threshold is configured and rewards always accrue.
    pub fn minimum_pool_size_to_activate(env: Env) -> i128 {
        balance::get_min_pool_size(&env)
    }

    /// Read-only: whether reward accrual is currently running.
    ///
    /// True when no threshold is configured, or when the pool has reached its
    /// threshold at least once.
    pub fn rewards_are_active(env: Env) -> bool {
        if balance::get_min_pool_size(&env) <= 0 {
            return true;
        }
        balance::get_rewards_activated_at(&env).is_some()
    }

    /// Read-only: the ledger at which reward accrual started, if it has.
    ///
    /// `None` while a threshold is configured that the pool has not yet
    /// reached. Returns `Some(0)` when no threshold is configured, since
    /// accrual was never gated.
    pub fn rewards_activated_at(env: Env) -> Option<u32> {
        if balance::get_min_pool_size(&env) <= 0 {
            return Some(0);
        }
        balance::get_rewards_activated_at(&env)
    }

    /// Read-only: how much more TVL the pool needs before rewards switch on.
    ///
    /// `0` once rewards are active (or no threshold is set).
    pub fn tvl_until_rewards_active(env: Env) -> i128 {
        let threshold = balance::get_min_pool_size(&env);
        if threshold <= 0 || balance::get_rewards_activated_at(&env).is_some() {
            return 0;
        }
        let total_staked = balance::get_total_deposited(&env);
        if total_staked >= threshold {
            return 0;
        }
        threshold - total_staked
    }

    /// Latch reward activation if the pool has reached its minimum size.
    ///
    /// Called after every TVL increase (and from
    /// `set_min_pool_size_to_activate`). Cheap and idempotent: once latched, or
    /// when no threshold is configured, it returns without writing.
    fn maybe_activate_rewards(env: &Env) {
        let threshold = balance::get_min_pool_size(env);
        if threshold <= 0 || balance::get_rewards_activated_at(env).is_some() {
            return;
        }
        let total_staked = balance::get_total_deposited(env);
        if total_staked < threshold {
            return;
        }
        let current_ledger = env.ledger().sequence();
        balance::set_rewards_activated_at(env, current_ledger);
        events::rewards_activated(env, total_staked, threshold, current_ledger);
    }

    /// The earliest ledger reward may accrue from, or `None` if accrual has not
    /// started yet.
    ///
    /// `Some(0)` when unrestricted, so callers can unconditionally clamp their
    /// window start against it.
    fn reward_accrual_floor(env: &Env) -> Option<u32> {
        if balance::get_min_pool_size(env) <= 0 {
            return Some(0);
        }
        balance::get_rewards_activated_at(env)
    }

    // ── Issue #235: Reward Smoothing ──────────────────────────────────────────

    /// Admin: spread large `add_yield` additions linearly over `period_ledgers`.
    ///
    /// Without smoothing, a lump-sum yield addition lands in a single ledger:
    /// whoever claims immediately after it captures a windfall, and anyone who
    /// claimed just before it misses out entirely. With `period_ledgers > 0`,
    /// any `add_yield` of at least `min_amount` is escrowed in the contract and
    /// credited to the pool linearly across the window instead, so the benefit
    /// tracks time staked rather than claim timing.
    ///
    /// `period_ledgers = 0` (the default) disables smoothing and restores the
    /// immediate-credit behaviour. `min_amount = 0` smooths every addition.
    /// Additions below `min_amount` are still credited immediately, since the
    /// timing distortion they cause is not worth the extra release step.
    pub fn set_reward_smoothing(
        env: Env,
        admin: Address,
        period_ledgers: u32,
        min_amount: i128,
    ) -> Result<(), VaultExtError> {
        admin::require_admin_as(&env, &admin)?;
        if period_ledgers > MAX_SMOOTHING_PERIOD_LEDGERS || min_amount < 0 {
            return Err(VaultExtError::InvalidSmoothingConfig);
        }

        // Settle whatever the current config has already vested before the new
        // period applies, so changing the config never reprices past ledgers.
        Self::settle_smoothing(&env);

        balance::set_smoothing_period(&env, period_ledgers);
        balance::set_smoothing_min_amount(&env, min_amount);
        Ok(())
    }

    /// Read-only: the configured `(period_ledgers, min_amount)` smoothing pair.
    pub fn get_reward_smoothing_config(env: Env) -> (u32, i128) {
        (
            balance::get_smoothing_period(&env),
            balance::get_smoothing_min_amount(&env),
        )
    }

    /// Read-only: state of the active reward smoothing schedule.
    ///
    /// All-zero when no addition has ever been smoothed. `releasable_now` is
    /// what `release_smoothed_yield()` would credit at this ledger.
    pub fn reward_smoothing(env: Env) -> SmoothingStatus {
        let schedule = match balance::get_smoothing_schedule(&env) {
            Some(schedule) => schedule,
            None => {
                return SmoothingStatus {
                    total_amount: 0,
                    released: 0,
                    releasable_now: 0,
                    unreleased: 0,
                    start_ledger: 0,
                    duration_ledgers: 0,
                    ledgers_remaining: 0,
                }
            }
        };

        let releasable_now = Self::releasable_smoothing(&env, &schedule);
        let elapsed = env
            .ledger()
            .sequence()
            .saturating_sub(schedule.start_ledger);

        SmoothingStatus {
            total_amount: schedule.total_amount,
            released: schedule.released,
            releasable_now,
            unreleased: schedule.total_amount.saturating_sub(schedule.released),
            start_ledger: schedule.start_ledger,
            duration_ledgers: schedule.duration_ledgers,
            ledgers_remaining: schedule.duration_ledgers.saturating_sub(elapsed),
        }
    }

    /// Credit the portion of the smoothing schedule that has vested so far.
    ///
    /// Permissionless: the released amount goes to every staker pro rata, so
    /// anyone may crank it. Returns the amount credited, `0` if nothing has
    /// vested since the last release. `stake`, `unstake`, and `claim` all crank
    /// this automatically, so calling it directly is only needed to make vested
    /// yield visible between user actions.
    pub fn release_smoothed_yield(env: Env) -> i128 {
        Self::settle_smoothing(&env)
    }

    /// The amount of `schedule` that has vested but not yet been credited.
    fn releasable_smoothing(env: &Env, schedule: &SmoothingSchedule) -> i128 {
        let outstanding = schedule.total_amount.saturating_sub(schedule.released);
        if outstanding <= 0 {
            return 0;
        }
        if schedule.duration_ledgers == 0 {
            return outstanding;
        }

        let elapsed = env
            .ledger()
            .sequence()
            .saturating_sub(schedule.start_ledger);
        if elapsed >= schedule.duration_ledgers {
            return outstanding;
        }

        // vested_total = total * elapsed / duration, then net off what's paid.
        let vested_total = schedule
            .total_amount
            .saturating_mul(elapsed as i128)
            .saturating_div(schedule.duration_ledgers as i128);
        vested_total.saturating_sub(schedule.released).max(0)
    }

    /// Credit any vested smoothing slice to `total_deposited`.
    ///
    /// Infallible by design (saturating math, no token movement — the tokens
    /// were already transferred in when the schedule was created) so it can be
    /// cranked from the stake/unstake/claim paths without threading an error
    /// through their signatures. Returns the amount credited.
    fn settle_smoothing(env: &Env) -> i128 {
        let mut schedule = match balance::get_smoothing_schedule(env) {
            Some(schedule) => schedule,
            None => return 0,
        };

        let releasable = Self::releasable_smoothing(env, &schedule);
        if releasable <= 0 {
            return 0;
        }

        schedule.released = schedule.released.saturating_add(releasable);
        balance::set_smoothing_schedule(env, &schedule);

        let total_deposited = balance::get_total_deposited(env);
        balance::set_total_deposited(env, total_deposited.saturating_add(releasable));
        Self::check_activation(env);
        Self::maybe_activate_rewards(env);

        events::smoothing_released(env, releasable, schedule.released, schedule.total_amount);

        releasable
    }

    /// Roll `amount` into the smoothing schedule, starting a fresh window.
    ///
    /// Any already-vested portion of an in-flight schedule is settled first,
    /// then whatever is still locked is carried into the new window alongside
    /// `amount`. Restarting the window on each addition keeps a single active
    /// schedule (bounding storage) while still delaying the new lump sum for a
    /// full period.
    fn schedule_smoothing(env: &Env, amount: i128, period_ledgers: u32) {
        Self::settle_smoothing(env);

        let carried_over = match balance::get_smoothing_schedule(env) {
            Some(schedule) => schedule.total_amount.saturating_sub(schedule.released),
            None => 0,
        };

        let start_ledger = env.ledger().sequence();
        let schedule = SmoothingSchedule {
            total_amount: carried_over.saturating_add(amount),
            released: 0,
            start_ledger,
            duration_ledgers: period_ledgers,
        };
        balance::set_smoothing_schedule(env, &schedule);

        events::smoothing_scheduled(env, schedule.total_amount, start_ledger, period_ledgers);
    }

    // ── Issue #236: Referral Tree Visualization ───────────────────────────────

    /// Read-only: the referral hierarchy rooted at `root`, flattened breadth-first.
    ///
    /// Builds on the existing referral system (`stake_with_referral`). Level 0
    /// is `root` itself, level 1 the addresses it referred, and so on up to
    /// `max_level` (default and maximum `MAX_REFERRAL_TREE_DEPTH`). Each node
    /// carries its own referral stats so a client can size nodes without a
    /// follow-up call per address.
    ///
    /// Returned flat rather than nested because `#[contracttype]` cannot
    /// express a recursive type; join `parent` against `address` to rebuild the
    /// hierarchy. Nodes appear in breadth-first order, so a parent always
    /// precedes its children.
    ///
    /// Two bounds keep the read cost finite: at most
    /// `balance::MAX_REFEREES_PER_NODE` children are tracked per node, and the
    /// walk stops after `MAX_REFERRAL_TREE_NODES` nodes. An address is emitted
    /// at most once even if it is reachable by several paths, which also makes
    /// the walk safe against the referral cycles the write path permits (A
    /// refers B, then B refers A).
    ///
    /// `root` is always returned, even with no referrals of its own.
    pub fn referral_tree_data(
        env: Env,
        root: Address,
        max_level: Option<u32>,
    ) -> Result<Vec<ReferralTreeNode>, VaultExtError> {
        let max_level = max_level.unwrap_or(MAX_REFERRAL_TREE_DEPTH);
        if max_level > MAX_REFERRAL_TREE_DEPTH {
            return Err(VaultExtError::ReferralDepthTooDeep);
        }

        let mut nodes: Vec<ReferralTreeNode> = Vec::new(&env);
        nodes.push_back(Self::referral_tree_node(&env, &root, &root, 0));

        // Breadth-first: `cursor` walks nodes already emitted, appending each
        // one's children until the level cap or the node budget is hit.
        let mut cursor = 0u32;
        while cursor < nodes.len() && nodes.len() < MAX_REFERRAL_TREE_NODES {
            let parent = nodes.get(cursor).unwrap();
            cursor += 1;

            if parent.level >= max_level {
                continue;
            }

            let referees = balance::get_referees(&env, &parent.address);
            let mut i = 0u32;
            while i < referees.len() && nodes.len() < MAX_REFERRAL_TREE_NODES {
                let referee = referees.get(i).unwrap();
                i += 1;
                if Self::tree_contains(&nodes, &referee) {
                    continue;
                }
                nodes.push_back(Self::referral_tree_node(
                    &env,
                    &referee,
                    &parent.address,
                    parent.level + 1,
                ));
            }
        }

        Ok(nodes)
    }

    /// Read-only: the addresses `referrer` directly referred (tree level 1).
    pub fn get_direct_referees(env: Env, referrer: Address) -> Vec<Address> {
        balance::get_referees(&env, &referrer)
    }

    fn referral_tree_node(
        env: &Env,
        address: &Address,
        parent: &Address,
        level: u32,
    ) -> ReferralTreeNode {
        let stats = balance::get_referral_stats(env, address);
        ReferralTreeNode {
            address: address.clone(),
            parent: parent.clone(),
            level,
            referred_count: stats.referee_count,
            total_referred_stake: stats.total_referred_deposits,
        }
    }

    fn tree_contains(nodes: &Vec<ReferralTreeNode>, address: &Address) -> bool {
        let mut i = 0u32;
        while i < nodes.len() {
            if &nodes.get(i).unwrap().address == address {
                return true;
            }
            i += 1;
        }
        false
    }

    // ── Issue #237: Capacity Auction ──────────────────────────────────────────

    /// Admin: open an auction allocating `spots` pool places to the highest bidders.
    ///
    /// When a pool cap is set and demand exceeds it, plain `stake` hands the
    /// remaining room to whoever arrives first. An auction replaces that race
    /// with a price: bidders escrow stake tokens over a fixed window, and when
    /// it closes the top `spots` bids become real staking positions while every
    /// losing bid is refunded in full.
    ///
    /// Bids are denominated in stake tokens and a winner's bid *is* their
    /// stake — nothing is burned or paid away, so the cost of outbidding a
    /// rival is committing more capital to the pool.
    ///
    /// Enable `set_auction_mode` to actually reserve the pool for auction
    /// winners; on its own this call only runs the auction.
    pub fn start_capacity_auction(
        env: Env,
        admin: Address,
        spots: u32,
        duration_ledgers: u32,
        min_bid: i128,
    ) -> Result<(), VaultExtError> {
        admin::require_admin_as(&env, &admin)?;

        if spots == 0 || spots > MAX_AUCTION_SPOTS || duration_ledgers == 0 || min_bid < 0 {
            return Err(VaultExtError::InvalidAuctionConfig);
        }

        // One auction at a time: an unfinalized auction still holds escrow that
        // must be settled before another round can start.
        if let Some(existing) = balance::get_capacity_auction(&env) {
            if !existing.finalized {
                return Err(VaultExtError::AuctionAlreadyActive);
            }
        }

        let started_at = env.ledger().sequence();
        let ends_at = started_at.saturating_add(duration_ledgers);
        let auction = CapacityAuction {
            spots,
            min_bid,
            started_at,
            ends_at,
            finalized: false,
            total_escrowed: 0,
        };
        balance::set_capacity_auction(&env, &auction);
        balance::set_auction_bids(&env, &Vec::new(&env));

        events::auction_started(&env, spots, min_bid, ends_at);
        Ok(())
    }

    /// Read-only: the current auction, or `None` if one was never started.
    pub fn capacity_auction(env: Env) -> Option<CapacityAuction> {
        balance::get_capacity_auction(&env)
    }

    /// Bid `amount` stake tokens for one of the auction's pool spots.
    ///
    /// The tokens move into the contract as escrow immediately. Bidding again
    /// tops up the existing bid rather than replacing it, so a bidder's rank is
    /// set by their cumulative commitment. Returns the bidder's total bid.
    ///
    /// A bid is only ever staked or refunded, never kept — a losing bidder gets
    /// every token back at finalization.
    pub fn place_bid(env: Env, bidder: Address, amount: i128) -> Result<i128, VaultExtError> {
        bidder.require_auth();

        if amount <= 0 {
            return Err(VaultExtError::ZeroAmount);
        }

        let mut auction =
            balance::get_capacity_auction(&env).ok_or(VaultExtError::AuctionNotFound)?;
        if auction.finalized {
            return Err(VaultExtError::AuctionClosed);
        }
        if env.ledger().sequence() >= auction.ends_at {
            return Err(VaultExtError::AuctionClosed);
        }

        let mut bids = balance::get_auction_bids(&env);

        // Locate an existing bid so repeat calls top up instead of duplicating.
        let mut existing_index: Option<u32> = None;
        let mut i = 0u32;
        while i < bids.len() {
            if bids.get(i).unwrap().bidder == bidder {
                existing_index = Some(i);
                break;
            }
            i += 1;
        }

        let previous = match existing_index {
            Some(index) => bids.get(index).unwrap().amount,
            None => 0,
        };
        let total_bid = previous
            .checked_add(amount)
            .ok_or(VaultExtError::ArithmeticError)?;
        if total_bid < auction.min_bid {
            return Err(VaultExtError::BidBelowMinimum);
        }
        if existing_index.is_none() && bids.len() >= MAX_AUCTION_BIDS {
            return Err(VaultExtError::TooManyBids);
        }

        let token_addr = Self::token_address(&env)?;
        let token_client = token::Client::new(&env, &token_addr);
        token_client.transfer(&bidder, &env.current_contract_address(), &amount);

        let entry = AuctionBid {
            bidder: bidder.clone(),
            amount: total_bid,
            // A top-up keeps the original timestamp so tie-breaking still
            // favours whoever committed first.
            placed_at: match existing_index {
                Some(index) => bids.get(index).unwrap().placed_at,
                None => env.ledger().sequence(),
            },
        };
        match existing_index {
            Some(index) => bids.set(index, entry),
            None => bids.push_back(entry),
        }
        balance::set_auction_bids(&env, &bids);

        auction.total_escrowed = auction.total_escrowed.saturating_add(amount);
        balance::set_capacity_auction(&env, &auction);

        events::bid_placed(&env, &bidder, amount, total_bid);
        Ok(total_bid)
    }

    /// Read-only: all live bids, highest first (ties broken by earliest bid).
    ///
    /// The leading `spots` entries are the current provisional winners.
    pub fn get_auction_bids(env: Env) -> Vec<AuctionBid> {
        Self::sorted_auction_bids(&env)
    }

    /// Read-only: the bid `bidder` currently has escrowed, `0` if none.
    pub fn get_bid_of(env: Env, bidder: Address) -> i128 {
        let bids = balance::get_auction_bids(&env);
        let mut i = 0u32;
        while i < bids.len() {
            let bid = bids.get(i).unwrap();
            if bid.bidder == bidder {
                return bid.amount;
            }
            i += 1;
        }
        0
    }

    /// Admin: close the auction, staking the winners and refunding the rest.
    ///
    /// Callable once the auction window has elapsed. Bids are ranked highest
    /// first and the top `spots` are converted into staking positions; every
    /// other bidder is refunded in full. Returns the number of winners.
    ///
    /// A winning bid that would push the pool past its cap is refunded instead
    /// of reverting, so one oversized bid cannot wedge the auction shut. For the
    /// same reason, if the pool is paused, stopped, or shutting down at
    /// finalization, nothing is staked and every bid is refunded.
    ///
    /// Returns `AuctionNotEnded` before `ends_at` and `AuctionClosed` on a
    /// second call, so escrow can never be paid out twice.
    pub fn finalize_capacity_auction(env: Env, admin: Address) -> Result<u32, VaultExtError> {
        admin::require_admin_as(&env, &admin)?;

        let mut auction =
            balance::get_capacity_auction(&env).ok_or(VaultExtError::AuctionNotFound)?;
        if auction.finalized {
            return Err(VaultExtError::AuctionClosed);
        }
        if env.ledger().sequence() < auction.ends_at {
            return Err(VaultExtError::AuctionNotEnded);
        }

        let token_addr = Self::token_address(&env)?;
        let token_client = token::Client::new(&env, &token_addr);
        let contract = env.current_contract_address();

        // Refund-only mode: a pool that cannot accept deposits right now must
        // not swallow escrow, so no bid is converted into a position.
        let staking_allowed = !Self::paused(&env)
            && !env
                .storage()
                .instance()
                .get(&DataKey::Stopped)
                .unwrap_or(false)
            && !env
                .storage()
                .instance()
                .get(&DataKey::ShuttingDown)
                .unwrap_or(false);

        let bids = Self::sorted_auction_bids(&env);
        let cap = balance::get_pool_cap(&env);

        let mut winner_count = 0u32;
        let mut total_staked = 0i128;
        let mut total_refunded = 0i128;

        let mut i = 0u32;
        while i < bids.len() {
            let bid = bids.get(i).unwrap();

            // Re-read TVL each iteration so the cap check accounts for the
            // winners already credited in this loop.
            let fits_cap =
                cap <= 0 || balance::get_total_deposited(&env).saturating_add(bid.amount) <= cap;
            let wins = staking_allowed && i < auction.spots && fits_cap;

            if wins {
                balance::grant_pool_spot(&env, &bid.bidder);
                Self::credit_escrow_stake(&env, &bid.bidder, bid.amount)?;
                winner_count += 1;
                total_staked = total_staked.saturating_add(bid.amount);
                events::auction_won(&env, &bid.bidder, bid.amount, i + 1);
            } else {
                token_client.transfer(&contract, &bid.bidder, &bid.amount);
                total_refunded = total_refunded.saturating_add(bid.amount);
                events::bid_refunded(&env, &bid.bidder, bid.amount);
            }

            i += 1;
        }

        auction.finalized = true;
        auction.total_escrowed = 0;
        balance::set_capacity_auction(&env, &auction);
        balance::set_auction_bids(&env, &Vec::new(&env));

        events::auction_finalized(&env, winner_count, total_staked, total_refunded);
        Ok(winner_count)
    }

    /// Admin: reserve the pool for auction winners.
    ///
    /// While enabled, `stake`/`deposit` reject any address that has not won a
    /// pool spot. Auction winners keep their spot permanently, so they can top
    /// up later. Disabled by default, which leaves staking open to everyone.
    pub fn set_auction_mode(env: Env, admin: Address, enabled: bool) -> Result<(), VaultExtError> {
        admin::require_admin_as(&env, &admin)?;
        balance::set_auction_mode(&env, enabled);
        Ok(())
    }

    /// Read-only: whether staking is restricted to auction winners.
    pub fn is_auction_mode(env: Env) -> bool {
        balance::get_auction_mode(&env)
    }

    /// Read-only: whether `user` holds a pool spot won at auction.
    pub fn has_pool_spot(env: Env, user: Address) -> bool {
        balance::has_pool_spot(&env, &user)
    }

    /// Bids ranked for allocation: descending amount, earliest bid wins ties.
    ///
    /// Insertion sort over at most `MAX_AUCTION_BIDS` entries.
    fn sorted_auction_bids(env: &Env) -> Vec<AuctionBid> {
        let bids = balance::get_auction_bids(env);
        let mut sorted: Vec<AuctionBid> = Vec::new(env);

        let mut i = 0u32;
        while i < bids.len() {
            let bid = bids.get(i).unwrap();

            let mut insert_at = sorted.len();
            let mut j = 0u32;
            while j < sorted.len() {
                let other = sorted.get(j).unwrap();
                if bid.amount > other.amount
                    || (bid.amount == other.amount && bid.placed_at < other.placed_at)
                {
                    insert_at = j;
                    break;
                }
                j += 1;
            }

            sorted.insert(insert_at, bid);
            i += 1;
        }

        sorted
    }

    /// Turn an already-escrowed auction bid into a staking position.
    ///
    /// Mirrors `do_stake_inner`'s bookkeeping but skips the token transfer —
    /// `place_bid` moved the tokens into the contract when the bid was
    /// placed — and skips `require_auth`, since the bidder authorized the
    /// transfer at bid time and the admin authorizes finalization. Whitelist,
    /// KYC, and min-stake gates are also skipped: winning the auction *is* the
    /// admission decision, and refusing a winner here would strand their
    /// escrow.
    fn credit_escrow_stake(
        env: &Env,
        staker: &Address,
        amount: i128,
    ) -> Result<i128, VaultExtError> {
        let total_shares = balance::get_total_shares(env);
        let total_deposited = balance::get_total_deposited(env);
        let current_shares = balance::get_shares(env, staker);

        Self::accrue_rewards(env, staker, current_shares)?;

        let shares = balance::amount_to_shares(total_shares, total_deposited, amount)
            .ok_or(VaultExtError::ArithmeticError)?;

        balance::set_shares(env, staker, current_shares + shares);
        balance::set_total_shares(env, total_shares + shares);
        balance::set_total_deposited(env, total_deposited + amount);
        Self::check_activation(env);
        Self::maybe_activate_rewards(env);

        let current_ledger = env.ledger().sequence();
        if current_shares == 0 {
            env.storage()
                .persistent()
                .set(&DataKey::StakedAtLedger(staker.clone()), &current_ledger);
            if !env
                .storage()
                .persistent()
                .has(&DataKey::FirstStakedAt(staker.clone()))
            {
                env.storage()
                    .persistent()
                    .set(&DataKey::FirstStakedAt(staker.clone()), &current_ledger);
            }
            balance::set_last_claim_ledger(env, staker, current_ledger);
            balance::set_total_stakers(env, balance::get_total_stakers(env) + 1);
            let mut all_stakers = balance::get_all_stakers(env);
            all_stakers.push_back(staker.clone());
            balance::set_all_stakers(env, &all_stakers);
            events::position_opened(env, staker, amount);
        }

        let new_shares = balance::get_shares(env, staker);
        Self::record_stake_snapshot(env, staker, new_shares);
        Self::update_leaderboard(env, staker, new_shares);
        Self::append_stake_history(env, staker, StakeAction::Stake, amount);

        events::deposit(env, staker, amount, shares, current_ledger);
        balance::set_last_updated_ledger(env, current_ledger);
        balance::set_total_ever_staked(env, balance::get_total_ever_staked(env) + amount);

        Ok(shares)
    }

    /// Issue #237. Reject stakers without a pool spot while auction mode is on.
    ///
    /// Reuses `NotWhitelisted` rather than introducing a dedicated error:
    /// `do_stake` returns `Result<i128, VaultError>`, and `VaultError` is
    /// already at Soroban's 50-variant cap (see the note on `VaultExtError`).
    /// The reuse also reads correctly — auction mode is an admission list whose
    /// members happen to be auction winners rather than addresses the admin
    /// named directly.
    fn require_pool_spot(env: &Env, staker: &Address) -> Result<(), VaultError> {
        if !balance::get_auction_mode(env) {
            return Ok(());
        }
        if !balance::has_pool_spot(env, staker) {
            return Err(VaultError::NotWhitelisted);
        }
        Ok(())
    }

    fn effective_rate_bps_for_window(env: &Env, start_ledger: u32, end_ledger: u32) -> u32 {
        let base_rate = balance::get_reward_rate_bps(env);
        if end_ledger <= start_ledger {
            return base_rate;
        }
        let config = match balance::get_bootstrap_config(env) {
            Some(c) => c,
            None => return base_rate,
        };

        let bootstrap_end = config.started_at.saturating_add(config.duration);
        let clip_start = start_ledger.max(config.started_at);
        let clip_end = end_ledger.min(bootstrap_end);
        if clip_end <= clip_start {
            return base_rate;
        }

        let window_len = (end_ledger - start_ledger) as u64;
        let bootstrap_ledgers = (clip_end - clip_start) as u64;
        let outside_ledgers = window_len - bootstrap_ledgers;

        // Average of a linear function over an interval equals its value at
        // the interval's midpoint.
        let mid = clip_start + (clip_end - clip_start) / 2;
        let bootstrap_avg_rate = Self::effective_rate_at_ledger(env, mid) as u64;

        let weighted =
            bootstrap_avg_rate * bootstrap_ledgers + (base_rate as u64) * outside_ledgers;
        (weighted / window_len) as u32
    }

    /// Read-only: returns time-weighted average APR over the last N ledgers.
    /// Calculates the weighted average of rates based on how many ledgers each rate was active.
    pub fn twap_apr_bps(env: Env, window_ledgers: u32) -> Result<u32, VaultError> {
        let _ = admin::get_admin(&env)?;

        if window_ledgers == 0 {
            return Ok(balance::get_reward_rate_bps(&env));
        }

        let current_ledger = env.ledger().sequence();
        let start_ledger = current_ledger.saturating_sub(window_ledgers);

        let history = balance::get_rate_history(&env);
        let current_rate = balance::get_reward_rate_bps(&env);

        // If no history, return current rate (assume it's been constant)
        if history.is_empty() {
            return Ok(current_rate);
        }

        // Build timeline: history stores (ledger, old_rate) meaning at that ledger, rate changed from old_rate to new
        // We need to reconstruct the rate timeline
        let mut weighted_sum: u64 = 0;
        let total_ledgers: u64 = window_ledgers as u64;

        // Each history entry (L, old_rate) means "at L, rate changed FROM old_rate".
        // The rate active FROM ledger L is the old_rate of the NEXT entry, or current_rate if last.
        // Find the first entry strictly after start_ledger.
        let mut index: u32 = 0;
        while index < history.len() {
            let (hist_ledger, _) = history.get(index).unwrap();
            if hist_ledger <= start_ledger {
                index += 1;
            } else {
                break;
            }
        }
        // Rate at start_ledger = old_rate of the first entry after start, or current_rate.
        let rate_at_start = if index < history.len() {
            let (_, next_old_rate) = history.get(index).unwrap();
            next_old_rate
        } else {
            current_rate
        };

        // Iterate through history entries within the window.
        let mut last_ledger = start_ledger;
        let mut last_rate = rate_at_start;

        while index < history.len() {
            let (hist_ledger, _) = history.get(index).unwrap();
            if hist_ledger < current_ledger {
                // hist_rate is the old rate that was active from last_ledger up to hist_ledger
                let duration = hist_ledger - last_ledger;
                weighted_sum += (duration as u64) * (last_rate as u64);
                last_ledger = hist_ledger;
                index += 1;
                // Rate active from hist_ledger = old_rate of next entry, or current_rate.
                last_rate = if index < history.len() {
                    let (_, next_old_rate) = history.get(index).unwrap();
                    next_old_rate
                } else {
                    current_rate
                };
            } else {
                break;
            }
        }

        // Add final segment from last change to current ledger with current rate
        let final_duration = current_ledger - last_ledger;
        weighted_sum += (final_duration as u64) * (current_rate as u64);

        // Calculate average using checked_div to avoid manual zero checks
        let avg = weighted_sum
            .checked_div(total_ledgers)
            .unwrap_or(current_rate as u64);
        Ok(avg as u32)
    }

    /// Read-only: returns full rate change history.
    pub fn get_rate_history(env: Env) -> Result<Vec<(u32, u32)>, VaultError> {
        let _ = admin::get_admin(&env)?;
        Ok(balance::get_rate_history(&env))
    }

    /// Read-only: returns the last 20 reward-rate changes as rich `RateHistoryEntry` records.
    ///
    /// Each entry records the old rate, new rate, the ledger at which the change
    /// was made, and the admin address that triggered it. Entries are in
    /// chronological order (oldest first). No auth required.
    ///
    /// Returns an empty vector if `set_reward_rate_bps` has never been called.
    pub fn get_reward_rate_history(env: Env) -> Vec<RateHistoryEntry> {
        balance::get_reward_rate_history(&env)
    }

    /// Admin: fund the separate reward pool used by `claim`.
    pub fn fund_reward_pool(env: Env, admin_addr: Address, amount: i128) -> Result<(), VaultError> {
        admin::require_admin_as(&env, &admin_addr)?;
        if amount <= 0 {
            return Err(VaultError::ZeroAmount);
        }

        let token_addr = Self::token_address(&env)?;

        let token_client = token::Client::new(&env, &token_addr);
        token_client.transfer(&admin_addr, &env.current_contract_address(), &amount);

        let reward_pool = balance::get_reward_pool_balance(&env);
        balance::set_reward_pool_balance(&env, reward_pool + amount);

        let admin_actual = admin::get_admin(&env)?;
        events::admin_action_fund_reward_pool(&env, &admin_actual, amount);
        balance::increment_admin_action_count(&env);

        Ok(())
    }

    /// Admin: set the percentage (basis points, max 500 = 5%) of every
    /// reward claim retained into the insurance fund instead of paid to the
    /// user (issue #199). `0` disables the feature.
    pub fn set_insurance_rate_bps(env: Env, bps: u32) -> Result<(), VaultExtError> {
        admin::require_admin(&env)?;
        if bps > 500 {
            return Err(VaultExtError::InvalidInsuranceRate);
        }
        balance::set_insurance_rate_bps(&env, bps);
        Ok(())
    }

    /// Read-only: the current insurance retention rate, in basis points.
    pub fn get_insurance_rate_bps(env: Env) -> u32 {
        balance::get_insurance_rate_bps(&env)
    }

    /// Read-only: current insurance fund balance (reward-token units).
    pub fn get_insurance_fund_balance(env: Env) -> i128 {
        balance::get_insurance_fund_balance(&env)
    }

    fn split_insurance_portion(env: &Env, reward: i128) -> (i128, i128) {
        let bps = balance::get_insurance_rate_bps(env);
        if bps == 0 || reward == 0 {
            return (reward, 0);
        }
        let user_reward = reward.saturating_mul(10_000 - bps as i128) / 10_000;
        let insurance_portion = reward - user_reward;
        (user_reward, insurance_portion)
    }

    /// Admin: move `amount` from the insurance fund into the reward pool to
    /// cover a shortfall (issue #199). Internal accounting only — no token
    /// transfer, since the insurance fund's tokens already sit in this
    /// contract's own balance (see `split_insurance_portion`).
    pub fn deploy_insurance_fund(
        env: Env,
        admin_addr: Address,
        amount: i128,
    ) -> Result<(), VaultExtError> {
        admin::require_admin_as(&env, &admin_addr)?;
        if amount <= 0 {
            return Err(VaultExtError::ZeroAmount);
        }
        let insurance_balance = balance::get_insurance_fund_balance(&env);
        if amount > insurance_balance {
            return Err(VaultExtError::ArithmeticError);
        }

        balance::set_insurance_fund_balance(&env, insurance_balance - amount);
        let reward_pool = balance::get_reward_pool_balance(&env);
        let new_reward_balance = reward_pool + amount;
        balance::set_reward_pool_balance(&env, new_reward_balance);

        events::insurance_deployed(&env, &admin_addr, amount, new_reward_balance);
        Ok(())
    }

    /// Read-only reward pool balance.
    pub fn get_reward_pool_balance(env: Env) -> Result<i128, VaultError> {
        let _ = admin::get_admin(&env)?;
        Ok(balance::get_reward_pool_balance(&env))
    }

    /// Admin: set the reward boost schedule, capped at five tiers.
    pub fn set_boost_schedule(env: Env, tiers: Vec<(u32, u32)>) -> Result<(), VaultError> {
        admin::require_admin(&env)?;
        if tiers.len() > MAX_BOOST_TIERS {
            return Err(VaultError::TooManyBoostTiers);
        }

        let mut last_ledger = 0;
        let mut index = 0;
        while index < tiers.len() {
            let (tier_ledger, multiplier_bps) = tiers.get(index).unwrap();
            if multiplier_bps < BOOST_BPS_BASE {
                return Err(VaultError::InvalidBoostSchedule);
            }
            if index > 0 && tier_ledger <= last_ledger {
                return Err(VaultError::InvalidBoostSchedule);
            }
            last_ledger = tier_ledger;
            index += 1;
        }

        let num_tiers = tiers.len();
        balance::set_boost_schedule(&env, &tiers);
        let admin = admin::get_admin(&env)?;
        events::admin_action_set_boost_schedule(&env, &admin, num_tiers);
        balance::increment_admin_action_count(&env);
        Ok(())
    }

    /// Read-only reward boost schedule.
    pub fn get_boost_schedule(env: Env) -> Result<Vec<(u32, u32)>, VaultError> {
        let _ = admin::get_admin(&env)?;
        Ok(balance::get_boost_schedule(&env).unwrap_or(Vec::new(&env)))
    }

    /// Current reward multiplier for a user, based on `staked_at_ledger`.
    pub fn get_boost_multiplier(env: Env, user: Address) -> Result<u32, VaultError> {
        let _ = admin::get_admin(&env)?;
        Ok(Self::boost_multiplier_for_ledger(
            &env,
            &user,
            env.ledger().sequence(),
        ))
    }

    /// Read-only: returns how far a user is toward the next boost tier.
    ///
    /// Computes the user's elapsed staking ledgers and walks the boost schedule
    /// to find which tier they currently qualify for and how many ledgers remain
    /// until the next one.  No auth required.
    pub fn get_boost_tier_progress(env: Env, user: Address) -> BoostTierProgress {
        let schedule = balance::get_boost_schedule(&env).unwrap_or(Vec::new(&env));
        let current_ledger = env.ledger().sequence();

        let staked_at: u32 = env
            .storage()
            .persistent()
            .get(&DataKey::StakedAtLedger(user.clone()))
            .unwrap_or(current_ledger);

        let elapsed = current_ledger.saturating_sub(staked_at);

        // Walk tiers to find which one the user currently qualifies for
        let mut current_tier: u32 = 0;
        let mut current_multiplier_bps: i128 = BOOST_BPS_BASE as i128;
        let mut next_tier_in_ledgers: Option<u32> = None;
        let mut next_multiplier_bps: Option<i128> = None;

        let mut i: u32 = 0;
        while i < schedule.len() {
            let (tier_threshold, tier_mult) = schedule.get(i).unwrap();
            if elapsed >= tier_threshold {
                // User has crossed this tier
                current_tier = i + 1;
                current_multiplier_bps = tier_mult as i128;
            } else {
                // This is the next tier the user hasn't reached yet
                next_tier_in_ledgers = Some(tier_threshold.saturating_sub(elapsed));
                next_multiplier_bps = Some(tier_mult as i128);
                break;
            }
            i += 1;
        }

        BoostTierProgress {
            current_tier,
            current_multiplier_bps,
            next_tier_in_ledgers,
            next_multiplier_bps,
        }
    }

    // ── Issue #181: combined reward multiplier preview ───────────────────────

    /// Read-only preview of `user`'s current effective reward rate with all
    /// active boosts (time-based tiers, campaign) stacked. No auth required,
    /// no state changes. Each multiplier field defaults to 10000 bps (1x) if
    /// that boost mechanism is not active for the user.
    pub fn reward_multiplier_preview(env: Env, user: Address) -> RewardMultiplierBreakdown {
        let current_ledger = env.ledger().sequence();
        let base_rate_bps = balance::get_reward_rate_bps(&env) as i128;

        let tier_multiplier_bps =
            Self::boost_multiplier_for_ledger(&env, &user, current_ledger) as i128;

        let campaign: Option<CampaignInfo> = env.storage().instance().get(&DataKey::BoostCampaign);
        let (campaign_multiplier_bps, _) = Self::campaign_info_at(current_ledger, &campaign);
        let campaign_multiplier_bps = campaign_multiplier_bps as i128;

        let effective_rate_bps = base_rate_bps
            .checked_mul(tier_multiplier_bps)
            .and_then(|v| v.checked_mul(campaign_multiplier_bps))
            .and_then(|v| v.checked_div(BOOST_BPS_BASE as i128))
            .and_then(|v| v.checked_div(BOOST_BPS_BASE as i128))
            .unwrap_or(0);

        RewardMultiplierBreakdown {
            base_rate_bps,
            tier_multiplier_bps,
            campaign_multiplier_bps,
            effective_rate_bps,
        }
    }

    // --- Issue #39: rescue stuck tokens ---

    /// Admin: register a separate reward token address (distinct from the stake token).
    /// Once set, `rescue_token` will also reject this token with CannotRescueRewardToken.
    pub fn set_reward_token(env: Env, token: Address) -> Result<(), VaultError> {
        admin::require_admin(&env)?;
        balance::set_reward_token(&env, &token);
        let admin = admin::get_admin(&env)?;
        events::admin_action_set_reward_token(&env, &admin, &token);
        balance::increment_admin_action_count(&env);
        Ok(())
    }

    /// Admin: transfer `amount` of a stuck non-stake, non-reward token to `recipient`.
    /// Rejects if the token is the stake token or the registered reward token.
    pub fn rescue_token(
        env: Env,
        admin_addr: Address,
        token: Address,
        amount: i128,
        recipient: Address,
    ) -> Result<(), VaultError> {
        admin::require_admin_as(&env, &admin_addr)?;

        if amount <= 0 {
            return Err(VaultError::ZeroAmount);
        }
        if recipient == env.current_contract_address() {
            return Err(VaultError::InvalidAddress);
        }

        let stake_token = Self::token_address(&env)?;

        if token == stake_token {
            return Err(VaultError::CannotRescueStakeToken);
        }

        if let Some(reward_token) = balance::get_reward_token(&env) {
            if token == reward_token {
                return Err(VaultError::CannotRescueRewardToken);
            }
        }

        let token_client = token::Client::new(&env, &token);
        token_client.transfer(&env.current_contract_address(), &recipient, &amount);

        events::token_rescued(&env, &token, amount, &recipient);
        events::admin_action_rescue_token(&env, &admin_addr, &token, amount, &recipient);
        balance::increment_admin_action_count(&env);

        Ok(())
    }

    /// Read-only query for the reward token balance held by the contract.
    ///
    /// Returns the current balance of the vault token in the contract's own
    /// account. This covers both staked principal and the funded reward pool,
    /// allowing integrators to assess whether the pool can sustain its current
    /// reward rate before staking. No auth required.
    pub fn reward_token_balance(env: Env) -> Result<i128, VaultError> {
        let token_addr = Self::token_address(&env)?;
        let balance =
            token::Client::new(&env, &token_addr).balance(&env.current_contract_address());
        Ok(balance)
    }

